                    public String type = r.getType().displayName;
                    public int capacity = r.getCapacity();
                    public String nightlyRate = String.format("%.2f", r.getNightlyRate());
                }).toList());
            } catch (Exception e) {
                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
            }
        });

