                long id = Long.parseLong(ctx.pathParam("id"));
                Reservation reservation = ReservationRepository.findById(id);

                if (reservation == null) {
                    ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", "Reservation not found"));
                    return;
